#!/usr/bin/env python3
"""patch_dressing_jobs.py -- the Layer 3 chain becomes three pipeline jobs.

level_factory 0.44.0, ZooAdapter 0.4.0, PatinaAdapter 0.4.0,
shape_metrics 0.3.1. Piece 4b of 5, and the last one before Presentation.

    zoo    --measure_shapes        -> <name>.metrics.json
    lot    (site_surfaces CLI)     -> surfaces.json
    patina --mode surface_dressing -> <site>.surface_dressing.json

Each job produces what the next consumes, which is how this pipeline already
works. It is deliberately NOT a new composite adapter: level_factory binds one
adapter per TOOL, each with its own `context["repository"]`, and a "surface
dressing" adapter would have no repository of its own.

WHY THE TWO ADAPTER VERSION BUMPS ARE LOAD-BEARING. PatinaAdapter's own 0.3.0
note says it: "the flags an adapter passes are not otherwise in the
fingerprint, so without it every dressing stage cache-hits and the pipeline
ships the covers it was told to stop making." Both adapters now plan
DIFFERENT COMMANDS. Without the bumps, every existing entry cache-hits and the
new artifacts are never produced at all.

THE PATH WALK, AND WHY IT IS CHECKED. `tools/shape_metrics.py` is a
factory-level tool -- it measures any GLB, not just Zoo's -- so the Zoo adapter
reaches it by walking up from its own location. A path walk is a silent
failure waiting to happen, so `validate_configuration` asserts the tool is
actually there: a repo layout change becomes a configuration error someone
reads, rather than a measurement that quietly stopped happening. The tool's
own SOURCE is in the fingerprint as well, because a change to how a footprint
is computed changes the catalogue the planner is built from while every other
input stays byte-identical -- the executes-a-sub-tool problem
`tests/test_presentation_fingerprint.py` was written for, one stage over.

`shape_metrics` also gains `--out`: a PlannedCommand is argv without a shell,
so `> file` is not available to it, and a tool that only writes to stdout
cannot be a pipeline step.

18 new tests, on the WIRING rather than the planning -- Patina's own 39 cover
the gates. What goes wrong at this layer is different in kind: a command never
planned, an input not in the fingerprint, a version not bumped when the
commands changed. Each is silent, and each produces a cache hit that ships the
wrong thing. Verified by reverting both adapters: the suite goes red.

=============================================================================
FOUND WHILE DOING THIS, AND DELIBERATELY NOT FIXED HERE:
level_factory/VERSION HAS GONE BACKWARDS.
=============================================================================

    CHANGELOG top entry ....... 0.43.3
    VERSION.pre_0433 .......... 0.43.2   (what the 0.43.3 patch saw)
    VERSION now ............... 0.22.0
    pyproject.toml version .... 0.22.0

VERSION was 0.43.2 and is now 0.22.0, and pyproject agrees with the wrong one.

Zoo's CHANGELOG records this exact failure once already -- "their CHANGELOG
entries did not survive a version reset that took VERSION backwards to
0.31.0." Same failure, different tool. Nothing noticed this time because
nothing in `packages/` reads VERSION at all, so there was no way for it to be
wrong loudly.

This patch numbers its CHANGELOG entry 0.44.0, following the CHANGELOG because
that is the live record. It does NOT touch VERSION or pyproject: renumbering a
package inside an unrelated feature patch is how the first reset happened, and
which number is right is a release decision, not this change's to make.

    python patch_dressing_jobs.py --check
    python patch_dressing_jobs.py --selftest
    python patch_dressing_jobs.py
    python patch_dressing_jobs.py --revert
"""
