def repo_root(start=None):
    d = os.path.abspath(start or os.path.dirname(os.path.abspath(__file__)))
    for _ in range(8):
        if (os.path.isdir(os.path.join(d, "level_factory", "adapters"))
                and os.path.isdir(os.path.join(d, "tools"))):
            return d
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    return None


def sha(b):
    return hashlib.sha256(b).hexdigest()


def rd(p):
    with open(p, "rb") as fh:
        return fh.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as fh:
        fh.write(b)


def plan(root):
    rows, ok = [], True
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        exists = os.path.isfile(p)
        if d["kind"] == "new":
            if exists and sha(rd(p)) == d["post_sha"]:
                rows.append((rel, "already-current", True))
            elif exists:
                rows.append((rel, "EXISTS AND DIFFERS - refusing", False))
                ok = False
            else:
                rows.append((rel, f"create {d['post_bytes']} B", True))
            continue
        if not exists:
            rows.append((rel, "MISSING - refusing", False))
            ok = False
            continue
        cur = sha(rd(p))
        if cur == d["post_sha"]:
            rows.append((rel, "already-current", True))
        elif cur == d["pre_sha"]:
            rows.append((rel, f"replace {d['pre_bytes']} -> {d['post_bytes']} B",
                         True))
        else:
            rows.append((rel, f"DRIFT sha {cur[:12]} != {d['pre_sha'][:12]}",
                         False))
            ok = False
    return ok, rows


def show(rows):
    w = max(len(r[0]) for r in rows)
    for rel, msg, good in rows:
        print(f"  {'ok ' if good else 'STOP'}  {rel:<{w}}  {msg}")


def apply(root):
    ok, rows = plan(root)
    show(rows)
    if not ok:
        print("\nREFUSING: nothing written. Resolve the lines marked STOP.")
        return 1
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        if os.path.isfile(p):
            cur = rd(p)
            if sha(cur) == d["post_sha"]:
                continue
            side = p + SIDECAR
            if not os.path.exists(side):
                wr(side, cur)
        wr(p, base64.b64decode(d["b64"]))
        assert sha(rd(p)) == d["post_sha"], rel
        n += 1
    print(f"\nWROTE {n} file(s). Sidecars: *{SIDECAR}")
    print("Next:")
    print("  python tools\\shape_metrics.py --selftest")
    print("  cd level_factory")
    print("  python -m pytest tests/test_dressing_jobs.py    # 18 new")
    print("  python -m pytest tests")
    print("Both adapter versions changed, so cached zoo and patina entries")
    print("will re-run. That is the point of the bump, not a side effect.")
    return 0


def revert(root):
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        side = p + SIDECAR
        if os.path.exists(side):
            wr(p, rd(side))
            os.remove(side)
            print(f"  reverted {rel}")
            n += 1
        elif d["kind"] == "new" and os.path.isfile(p):
            if sha(rd(p)) == d["post_sha"]:
                os.remove(p)
                print(f"  removed  {rel} (this patch created it)")
                n += 1
            else:
                print(f"  KEPT     {rel} (modified since; not ours to delete)")
    print(f"reverted {n} file(s)")
    return 0


def selftest():
    bad = 0

    def fail(msg):
        nonlocal bad
        print(f"  FAIL  {msg}")
        bad += 1

    print("patch_dressing_jobs selftest")

    for rel, d in PAYLOAD.items():
        b = base64.b64decode(d["b64"])
        if sha(b) != d["post_sha"] or len(b) != d["post_bytes"]:
            fail(f"payload {rel} does not match its recorded hash/size")
    print(f"  ok    {len(PAYLOAD)} payloads decode to their recorded hashes")

    import ast

    def src(rel):
        return base64.b64decode(PAYLOAD[rel]["b64"]).decode("utf-8")

    zoo = src("level_factory/adapters/zoo/__init__.py")
    pat = src("level_factory/adapters/patina/__init__.py")
    met = src("tools/shape_metrics.py")
    tst = src("level_factory/tests/test_dressing_jobs.py")

    def class_attr(source, cls, attr):
        for node in ast.parse(source).body:
            if isinstance(node, ast.ClassDef) and node.name == cls:
                for st in node.body:
                    if isinstance(st, ast.Assign) and any(
                            isinstance(t, ast.Name) and t.id == attr
                            for t in st.targets):
                        v = st.value
                        # `capabilities = frozenset({...})` is a CALL, not a
                        # literal, and literal_eval raises on it. Unwrap the
                        # one argument rather than regex the source.
                        if isinstance(v, ast.Call) and \
                                isinstance(v.func, ast.Name) and \
                                v.func.id in ("frozenset", "set") and v.args:
                            v = v.args[0]
                        return ast.literal_eval(v)
        return None

    # FALSIFICATION: the version bumps are the whole reason the new commands
    # ever run. If either is missed, every existing entry cache-hits and the
    # new artifacts are silently never produced -- which looks exactly like a
    # working pipeline.
    zv = class_attr(zoo, "ZooAdapter", "adapter_version")
    pv = class_attr(pat, "PatinaAdapter", "adapter_version")
    if zv != "0.4.0":
        fail(f"ZooAdapter.adapter_version is {zv!r}, expected 0.4.0")
    if pv != "0.4.0":
        fail(f"PatinaAdapter.adapter_version is {pv!r}, expected 0.4.0")
    print(f"  ok    ZooAdapter {zv} and PatinaAdapter {pv} are both bumped")

    for source, cls, cap in ((zoo, "ZooAdapter", "measure_shapes"),
                             (pat, "PatinaAdapter", "surface_dressing")):
        caps = class_attr(source, cls, "capabilities")
        if not caps or cap not in caps:
            fail(f"{cls} does not declare the {cap} capability")
    print("  ok    both new capabilities are declared")

    # The path walk must be checked, not merely performed.
    if "SHAPE_METRICS" not in zoo:
        fail("the zoo adapter does not locate shape_metrics")
    if "SHAPE_METRICS.is_file()" not in zoo:
        fail("the path walk is never checked; a layout change would silently "
             "stop the measurement instead of failing")
    if "shape_metrics_hash" not in zoo:
        fail("the measuring tool's own source is not in the fingerprint")
    print("  ok    the path walk is checked and the tool's source is hashed")

    # A PlannedCommand is argv without a shell.
    if "--out" not in met:
        fail("shape_metrics has no --out, so it cannot be a pipeline step")
    if 'VERSION = "0.3.1"' not in met:
        fail("shape_metrics VERSION was not bumped")
    print("  ok    shape_metrics 0.3.1 can write to a file")

    # Patina's dressing mode must plan a DIFFERENT command and always audit.
    if "patina.surface_dressing" not in pat:
        fail("the patina adapter never plans the dressing planner")
    if '"--audit"' not in pat:
        fail("the dressing job does not audit, so an illegal plan would "
             "travel downstream instead of failing the job")
    print("  ok    the dressing job plans the planner and always audits")

    for needle in ("test_measuring_changes_the_fingerprint",
                   "test_dressing_and_art_modes_fingerprint_differently",
                   "test_the_art_path_is_untouched"):
        if needle not in tst:
            fail(f"no test named {needle}")
    print("  ok    fingerprint separation and the untouched art path are "
          "both pinned")

    ch = src("level_factory/CHANGELOG.md")
    if not ch.startswith("## [0.44.0]") or "## [0.43.3]" not in ch:
        fail("CHANGELOG is not 0.44.0 on top of 0.43.3")
    if "VERSION HAS GONE BACKWARDS" not in ch.upper():
        fail("the CHANGELOG does not record the VERSION regression")
    if "level_factory/VERSION" in PAYLOAD or \
            "level_factory/pyproject.toml" in PAYLOAD:
        fail("this patch touches VERSION or pyproject; it is documented as "
             "deliberately leaving them alone")
    print("  ok    0.44.0 recorded, VERSION regression documented, neither "
          "VERSION nor pyproject touched")

    ref = base64.b64decode(next(iter(PAYLOAD.values()))["b64"])
    mut = bytearray(ref)
    mut[len(mut) // 2] ^= 0x20
    if sha(bytes(mut)) == sha(ref):
        fail("a mutated payload hashed identically")
    else:
        print("  ok    one flipped byte changes the hash")

    print("SELFTEST", "PASSED" if bad == 0 else f"FAILED ({bad})")
    return 1 if bad else 0


def main(argv):
    if "--selftest" in argv:
        return selftest()
    root = None
    if "--root" in argv:
        root = os.path.abspath(argv[argv.index("--root") + 1])
    root = root or repo_root()
    if not root:
        print("Could not find the gabagool_factory root. Pass --root <path>.")
        return 2
    print(f"repo root: {root}")
    if "--revert" in argv:
        return revert(root)
    ok, rows = plan(root)
    if "--check" in argv:
        show(rows)
        print("\n--check only: nothing written."
              + ("" if ok else "  RESOLVE THE STOP LINES FIRST."))
        return 0 if ok else 1
    return apply(root)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
